pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix(r#"{"v":2,"hello":"#) {
        if let Some(value) = value.strip_suffix('}') {
            if let Some(value) = value.strip_suffix('"') {
                return Ok(Msg::Hello(value.to_string()));
            }
        }
    }
    if let Some(value) = bytes.strip_prefix(r#"{"v":2,"heartbeat":"#) {
        if let Some(value) = value.strip_suffix("}") {
            if let Ok(sequence) = value.parse() {
                return Ok(Msg::Heartbeat(sequence));
            }
        }
    }
    Err("unknown".into())
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, value),
        Msg::Heartbeat(sequence) => format!(r#"{{"v":2,"heartbeat":{}}}"#, sequence),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }
    #[test]
    fn hello_roundtrips_with_v2_envelope() {
        let msg = Msg::Hello("Ada".into());
        assert_eq!(encode(&msg), r#"{"v":2,"hello":"Ada"}"#);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(name)) if name == "Ada"));
    }
    #[test]
    fn heartbeat_roundtrips_with_sequence_number() {
        let msg = Msg::Heartbeat(42);
        assert_eq!(encode(&msg), r#"{"v":2,"heartbeat":42}"#);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
